def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of exactly K moves through distinct empty adjacent cells."""
    neighbors = [[] for _ in range(H * W)]
    starts = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != ".":
                continue
            cell = r * W + c
            starts.append(cell)
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == ".":
                    neighbors[cell].append(nr * W + nc)

    if K >= len(starts):
        return 0
    visited = [False] * (H * W)

    def dfs(cell, remaining):
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += dfs(nxt, remaining - 1)
                visited[nxt] = False
        return total

    answer = 0
    for start in starts:
        visited[start] = True
        answer += dfs(start, K)
        visited[start] = False
    return answer

