from math import isqrt


def find_largest_400_number(a: int) -> int:
    """Find the largest number <= a with exactly two prime factors, both
    occurring to even exponents (36 <= a <= 10**12).
    """
    # Such numbers are exactly squares whose roots have two distinct primes.
    # Roots are at most 10**6, so trial division requires primes <= 1000.
    limit = isqrt(isqrt(a))
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * ((limit - start) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    for root in range(isqrt(a), 5, -1):
        remaining = root
        distinct = 0
        for p in primes:
            if p * p > remaining:
                break
            if remaining % p == 0:
                distinct += 1
                while remaining % p == 0:
                    remaining //= p
                if distinct > 2:
                    break
        if remaining > 1:
            distinct += 1
        if distinct == 2:
            return root * root
    # The documented lower bound guarantees that 36 is available.
    return 36

