from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return counts for lengths 0 through n, modulo 998244353.
    The constraints are 1 <= n <= 10 and 1 <= m <= 100.
    """
    mod = 998244353
    letter_masks = {}
    for i, char in enumerate(s):
        letter_masks[char] = letter_masks.get(char, 0) | (1 << i)

    # A state stores the differences between adjacent entries of an LCS
    # DP row. Every difference is zero or one, so n bits encode the row.
    size = 1 << n
    transitions = []
    for state in range(size):
        destinations = {}
        absent = 26 - len(letter_masks)
        if absent:
            destinations[state] = absent
        for mask in letter_masks.values():
            matches = state | mask
            target = matches & ~(matches - ((state << 1) | 1))
            destinations[target] = destinations.get(target, 0) + 1
        transitions.append(tuple(destinations.items()))

    counts = [0] * size
    counts[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, count in enumerate(counts):
            if count:
                for target, multiplicity in transitions[state]:
                    following[target] += count * multiplicity
        counts = [count % mod for count in following]

    answer = [0] * (n + 1)
    for state, count in enumerate(counts):
        answer[state.bit_count()] = (answer[state.bit_count()] + count) % mod
    return answer

