from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree with degrees 1 or 4 and a degree-4 vertex.

    Vertices are numbered 1 through n. Return -1 if none exists.
    Uses O(n) time and space without recursive traversal.
    """
    adjacency = [[] for _ in range(n + 1)]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)

    parent = [0] * (n + 1)
    order = [1]
    for v in order:
        for w in adjacency[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    # branch[v] includes v and assumes its edge to its parent is selected.
    # Thus v either is a leaf or takes exactly three child branches.
    branch = [1] * (n + 1)
    answer = -1
    for v in reversed(order):
        first = second = third = fourth = 0
        for w in adjacency[v]:
            if parent[w] != v:
                continue
            value = branch[w]
            if value >= first:
                first, second, third, fourth = value, first, second, third
            elif value >= second:
                second, third, fourth = value, second, third
            elif value >= third:
                third, fourth = value, third
            elif value > fourth:
                fourth = value
        if third:
            branch[v] = 1 + first + second + third
        # The topmost vertex can be a leaf with one nontrivial child branch,
        # or a degree-4 vertex taking four child branches.
        if first > 1:
            answer = max(answer, 1 + first)
        if fourth:
            answer = max(answer, 1 + first + second + third + fourth)
    return answer

